import{_ as t,o as d,c as o,ae as a}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started.","frontmatter":{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result classes returned when a payment is started."},"headers":[],"relativePath":"python-myanmar-payments/references/results.md","filePath":"python-myanmar-payments/references/results.md"}'),r={name:"python-myanmar-payments/references/results.md"};function c(n,e,s,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns one of four frozen dataclasses exported from <code>python_myanmar_payments</code>. Each has a <code>flow</code> class attribute, and <code>PaymentResult</code> is their union, so a <code>match</code> statement or <code>isinstance</code> check tells them apart. Fields a gateway did not provide are <code>None</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>kbz.pwa()</code> and <code>wave.initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow.REDIRECT</code></td></tr><tr><td><code>order_id</code></td><td><code>str</code></td><td>Your order ID, as sent to the gateway</td></tr><tr><td><code>url</code></td><td><code>str</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>gateway_reference</code></td><td><code>str | None</code></td><td>The gateway&#39;s ID for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>Mapping[str, Any]</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>aya.initiate()</code> and <code>cs.initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow.FORM</code></td></tr><tr><td><code>order_id</code></td><td><code>str</code></td><td>Your order ID</td></tr><tr><td><code>action</code></td><td><code>str</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>fields</code></td><td><code>tuple[FormField, ...]</code></td><td>The signed hidden fields in order. Post them unchanged</td></tr><tr><td><code>enctype</code></td><td><code>str</code></td><td>The encoding the gateway expects; <code>application/x-www-form-urlencoded</code> unless the gateway needs another (AYA: <code>multipart/form-data</code>)</td></tr><tr><td><code>to_html()</code></td><td><code>str</code></td><td>A complete, escaped page that submits the form on load</td></tr><tr><td><code>field(name)</code></td><td><code>str | None</code></td><td>One field&#39;s value</td></tr><tr><td><code>values()</code></td><td><code>dict[str, str]</code></td><td>The fields as a <code>dict</code></td></tr></tbody></table><p><code>FormField</code> is a frozen dataclass with <code>name: str</code> and <code>value: str</code>.</p><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>kbz.qr()</code>, <code>yoma.initiate()</code> and <code>yoma.renew_qr()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow.QR</code></td></tr><tr><td><code>order_id</code></td><td><code>str</code></td><td>Your order ID</td></tr><tr><td><code>qr_string</code></td><td><code>str | None</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>qr_image</code></td><td><code>str | None</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>expires_at</code></td><td><code>datetime | None</code></td><td>When the QR stops being payable, as an aware UTC <code>datetime</code>; <code>None</code> when the gateway sets no limit</td></tr><tr><td><code>reference</code></td><td><code>str | None</code></td><td>The gateway&#39;s ID for this QR, used for status checks (Yoma <code>refLabel</code>, KBZ <code>prepay_id</code>)</td></tr><tr><td><code>raw</code></td><td><code>Mapping[str, Any]</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>qr_image_data_uri(mime_type=&quot;image/png&quot;)</code></td><td><code>str | None</code></td><td><code>qr_image</code> as a data URI. <code>None</code> when there is no image</td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>kbz.app()</code>. <code>payment.to_dict()</code> returns <code>orderId</code>, <code>orderInfo</code>, <code>sign</code> and <code>signType</code>, the names the KBZ Pay SDK uses.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>flow</code></td><td><code>PaymentFlow</code></td><td><code>PaymentFlow.APP</code></td></tr><tr><td><code>order_id</code></td><td><code>str</code></td><td>Your order ID</td></tr><tr><td><code>order_info</code></td><td><code>str</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>sign</code></td><td><code>str</code></td><td>The signature of <code>order_info</code></td></tr><tr><td><code>sign_type</code></td><td><code>str</code></td><td>The signature algorithm, <code>SHA256</code></td></tr><tr><td><code>raw</code></td><td><code>Mapping[str, Any]</code></td><td>The gateway&#39;s response; left out of <code>to_dict()</code></td></tr><tr><td><code>to_dict()</code></td><td><code>dict[str, str]</code></td><td><code>{&quot;orderId&quot;, &quot;orderInfo&quot;, &quot;sign&quot;, &quot;signType&quot;}</code>, the values your app needs</td></tr></tbody></table><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><p>A <code>str</code> enum, so <code>payment.flow == &quot;redirect&quot;</code> works too.</p><table tabindex="0"><thead><tr><th>Member</th><th>Value</th><th>Class</th></tr></thead><tbody><tr><td><code>PaymentFlow.REDIRECT</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>PaymentFlow.FORM</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>PaymentFlow.QR</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>PaymentFlow.APP</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table><p><code>raw</code> values are plain Python values: every JSON number is its exact text as a <code>str</code> (<code>1000.50</code> stays <code>&quot;1000.50&quot;</code>), never a <code>float</code>, so <code>json.dumps(payment.raw)</code> logs them as is.</p><p>Every result class takes its fields as keyword arguments, so you can build one in your own tests, e.g. <code>RedirectPayment(order_id=&quot;ORDER_1&quot;, url=&quot;https://…&quot;)</code>.</p>',20)])])}const y=t(r,[["render",c]]);export{p as __pageData,y as default};
